def schema_json(name: str) -> dict[str, Any]:
    """Return the packaged, byte-identical copy of contracts/schemas/<name>.schema.json."""
    if name not in SCHEMA_NAMES:
        msg = f"unknown schema {name!r}"
        raise KeyError(msg)
    resource = files("veyltrace_contracts") / "schemas" / f"{name}.schema.json"
    parsed: dict[str, Any] = json.loads(resource.read_bytes().decode("utf-8"))
    return parsed
